// Catalogue selection stays off the render thread; native embeds resolve films.
import './catalogue-selection.js?v=neon1';
import './catalogue-metadata.js?v=neon1';
const metadata=new CatalogueMetadata();let rows,index,byId,neon,deck=[],cursor=0;const seen=new Set();
async function catalogue(){if(rows)return index;const [data,n]=await Promise.all([metadata.retro(),metadata.neon()]);neon=n;rows=[...data.rows,...n.films.filter(f=>!data.byId.has(f.id))];index={...data.index,neon:{total:n.total,spots:n.spots,withoutYouTube:n.withoutYouTube,facets:n.facets}};byId=new Map([...data.byId,...n.byId]);return index;}
async function configure(options={}){await catalogue();const selection=CatalogueSelection.normalize({...options,source:options.source==='mia'?'mixed':options.source,mix:100});deck=[];for(let i=0;i<rows.length;i++){const row=rows[i],film=Array.isArray(row)?{tags:row[1]}:row,id=Array.isArray(row)?'yt:'+row[0]:row.id;if(CatalogueSelection.accepts(id,film,selection))deck.push(i);}for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}cursor=0;return {...index,selected:deck.length};}
function describe(row){if(!Array.isArray(row))return {...row,direct:true,captionStatus:'loading',categories:[...new Set(row.entries.map(e=>e.category))]};return {youtubeId:row[0],id:'yt:'+row[0],title:'YouTube · '+row[0],year:row[1][0]?.[0],categories:[...new Set(row[1].map(x=>index.categories[x[1]]))],tags:row[1],page:'https://www.youtube.com/watch?v='+row[0],catalogue:'https://www.myretrotvs.com/',direct:true,duration:0,captionStatus:'loading'};}
onmessage=async({data})=>{try{let result;if(data.type==='configure')result=await configure(data.options);else if(data.type==='take'){if(!Number.isSafeInteger(data.count)||data.count<1)throw Error('Catalogue selection requires a positive record count');await catalogue();const list=[];while(list.length<data.count&&cursor<deck.length){const row=rows[deck[cursor++]];const id=Array.isArray(row)?row[0]:row.youtubeId;if(seen.has(id))continue;seen.add(id);list.push(describe(row));}result={items:list,remaining:deck.length-cursor};}else if(data.type==='resolve'){await catalogue();result=describe(byId.get('yt:'+data.id)||[data.id,[]]);}else throw Error('Unknown source request');postMessage({requestId:data.requestId,result});}catch(e){postMessage({requestId:data.requestId,error:e.message});}};
